init_esm();
function _endOfDayIfDateOnly(raw2) {
  const d = new Date(raw2);
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw2)) {
    d.setUTCHours(23, 59, 59, 999);
  }
  return d;
}

class AttendanceRepository {
  async create(data) {
    return await db2.insertInto("attendance").values(data).returningAll().executeTakeFirstOrThrow();
  }
  async findTodayStatus(userId) {
    const today = new Date;
    today.setHours(0, 0, 0, 0);
    return await db2.selectFrom("attendance").selectAll().where("userId", "=", userId).where("serverTime", ">=", today).orderBy("serverTime", "desc").execute();
  }
  async findAll(filters) {
    let base = db2.selectFrom("attendance").innerJoin("user", "user.id", "attendance.userId");
    if (filters.userId) {
      base = base.where("attendance.userId", "=", filters.userId);
    }
    if (filters.from) {
      base = base.where("attendance.serverTime", ">=", new Date(filters.from));
    }
    if (filters.to) {
      base = base.where("attendance.serverTime", "<=", _endOfDayIfDateOnly(filters.to));
    }
    if (filters.department) {
      base = base.where("user.department", "=", filters.department);
    }
    if (filters.type) {
      base = base.where("attendance.type", "=", filters.type);
    }
    const offset = (filters.page - 1) * filters.limit;
    const [items, countResult] = await Promise.all([
      base.select([
        "attendance.id",
        "attendance.type",
        "attendance.photoUrl",
        "attendance.latitude",
        "attendance.longitude",
        "attendance.locationName",
        "attendance.isWithinZone",
        "attendance.serverTime",
        "user.id as userId",
        "user.name as userName",
        "user.department as userDepartment"
      ]).limit(filters.limit).offset(offset).orderBy("attendance.serverTime", "desc").execute(),
      base.select(sql`count(*)`.as("count")).executeTakeFirst()
    ]);
    const total = Number(countResult?.count ?? 0);
    return {
      items,
      page: filters.page,
      limit: filters.limit,
      total
    };
  }
  async findRecapData(filters) {
    let query = db2.selectFrom("attendance").innerJoin("user", "user.id", "attendance.userId").select([
      "attendance.userId",
      "attendance.type",
      "attendance.serverTime",
      "attendance.isWithinZone",
      "user.name as userName",
      "user.department as userDepartment"
    ]).where("attendance.serverTime", ">=", new Date(filters.from)).where("attendance.serverTime", "<=", _endOfDayIfDateOnly(filters.to)).orderBy("attendance.userId").orderBy("attendance.serverTime", "asc");
    if (filters.userId) {
      query = query.where("attendance.userId", "=", filters.userId);
    }
    if (filters.department) {
      query = query.where("user.department", "=", filters.department);
    }
    return await query.execute();
  }
  async findMonthlyByUser(userId, start, end) {
    return await db2.selectFrom("attendance").select([
      "id",
      "type",
      "serverTime",
      "isLate"
    ]).where("userId", "=", userId).where("serverTime", ">=", start).where("serverTime", "<=", end).orderBy("serverTime", "asc").execute();
  }
  async findMapPoints(start, end) {
    return await db2.selectFrom("attendance").innerJoin("user", "user.id", "attendance.userId").select([
      "attendance.id as attendanceId",
      "attendance.userId",
      "user.name as userName",
      "attendance.type",
      "attendance.latitude",
      "attendance.longitude",
      "attendance.locationName",
      "attendance.isWithinZone",
      "attendance.serverTime"
    ]).where("attendance.serverTime", ">=", start).where("attendance.serverTime", "<=", end).execute();
  }
}

