// src/modules/report/report.repository.ts
init_esm();

class ReportRepository {
  async create(data) {
    return await db2.insertInto("fieldReport").values(data).returningAll().executeTakeFirstOrThrow();
  }
  async findById(id2) {
    return await db2.selectFrom("fieldReport").leftJoin("reportValidation", "reportValidation.reportId", "fieldReport.id").innerJoin("user", "user.id", "fieldReport.userId").select([
      "fieldReport.id",
      "fieldReport.category",
      "fieldReport.description",
      "fieldReport.photoUrl",
      "fieldReport.latitude",
      "fieldReport.longitude",
      "fieldReport.status",
      "fieldReport.createdAt",
      "user.name as userName",
      "user.department as userDepartment",
      "reportValidation.status as validationStatus",
      "reportValidation.notes as validationNotes",
      "reportValidation.validatedAt as validationDate"
    ]).where("fieldReport.id", "=", id2).executeTakeFirst();
  }
  async findAll(filters) {
    let base = db2.selectFrom("fieldReport").innerJoin("user", "user.id", "fieldReport.userId");
    if (filters.status) {
      base = base.where("fieldReport.status", "=", filters.status);
    }
    if (filters.category) {
      base = base.where("fieldReport.category", "=", filters.category);
    }
    if (filters.userId) {
      base = base.where("fieldReport.userId", "=", filters.userId);
    }
    if (filters.from) {
      base = base.where("fieldReport.createdAt", ">=", new Date(filters.from));
    }
    if (filters.to) {
      base = base.where("fieldReport.createdAt", "<=", new Date(filters.to));
    }
    const offset = (filters.page - 1) * filters.limit;
    const [items, countResult] = await Promise.all([
      base.select([
        "fieldReport.id",
        "fieldReport.category",
        "fieldReport.description",
        "fieldReport.photoUrl",
        "fieldReport.status",
        "fieldReport.createdAt",
        "user.name as userName",
        "user.department as userDepartment"
      ]).limit(filters.limit).offset(offset).orderBy("fieldReport.createdAt", "desc").execute(),
      base.select(sql`count(*)`.as("count")).executeTakeFirst()
    ]);
    const total = Number(countResult?.count ?? 0);
    return {
      items,
      page: filters.page,
      limit: filters.limit,
      total
    };
  }
  async validate(reportId, validationData) {
    return await db2.transaction().execute(async (trx) => {
      await trx.insertInto("reportValidation").values(validationData).execute();
      await trx.updateTable("fieldReport").set({ status: validationData.status }).where("id", "=", reportId).execute();
    });
  }
}

// src/modules/report/report.schema.ts
var createReportSchema = exports_external.object({
  category: exports_external.enum(["weather", "technical", "progress", "other"]),
  description: exports_external.string().min(10).max(500),
  latitude: exports_external.coerce.number().min(-90).max(90),
  longitude: exports_external.coerce.number().min(-180).max(180)
});
var validateReportSchema = exports_external.object({
  status: exports_external.enum(["approved", "rejected", "need_revision"]),
  notes: exports_external.string().optional()
});
var reportQuerySchema = exports_external.object({
  page: exports_external.coerce.number().min(1).default(1),
  limit: exports_external.coerce.number().min(1).max(100).default(10),
  status: exports_external.enum(["pending", "approved", "rejected", "need_revision"]).optional(),
  category: exports_external.enum(["weather", "technical", "progress", "other"]).optional(),
  userId: exports_external.string().optional(),
  from: exports_external.string().optional(),
  to: exports_external.string().optional()
});

// src/modules/report/report.modul.ts
class ReportModule {
  repository = new ReportRepository;
  async processCreate(userId, body) {
    const validated = createReportSchema.safeParse(body);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid data", details: validated.error.flatten() }, status: 422 };
    }
    const photo = body["photo"];
    if (!photo) {
      return { error: { code: "MISSING_PHOTO", message: "Photo is required" }, status: 422 };
    }
    const arrayBuf = await photo.arrayBuffer();
    const watermarked = await watermarkPhoto(Buffer.from(arrayBuf), {
      latitude: validated.data.latitude,
      longitude: validated.data.longitude,
      serverTime: new Date
    });
    const key = `reports/${userId}-${crypto.randomUUID()}.jpg`;
    const photoUrl = await uploadToR2(watermarked, key, "image/jpeg");
    const data = await this.repository.create({
      id: crypto.randomUUID(),
      userId,
      category: validated.data.category,
      description: validated.data.description,
      photoUrl,
      latitude: validated.data.latitude,
      longitude: validated.data.longitude,
      status: "pending"
    });
    return { data, status: 201 };
  }
  async fetchMyReports(userId, query) {
    const validated = reportQuerySchema.safeParse(query);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid query parameters" }, status: 422 };
    }
    const result = await this.repository.findAll({
      ...validated.data,
      userId
    });
    return { data: result, status: 200 };
  }
  async fetchAllReports(query) {
    const validated = reportQuerySchema.safeParse(query);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid query parameters" }, status: 422 };
    }
    const result = await this.repository.findAll(validated.data);
    return { data: result, status: 200 };
  }
  async fetchDetail(id2) {
    const data = await this.repository.findById(id2);
    if (!data) {
      return { error: { code: "REPORT_NOT_FOUND", message: "Report not found" }, status: 404 };
    }
    return { data, status: 200 };
  }
  async processValidate(reportId, userId, body) {
    const validated = validateReportSchema.safeParse(body);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid data", details: validated.error.flatten() }, status: 422 };
    }
    const report = await this.repository.findById(reportId);
    if (!report) {
      return { error: { code: "REPORT_NOT_FOUND", message: "Report not found" }, status: 404 };
    }
    if (report.status !== "pending") {
      return { error: { code: "ALREADY_VALIDATED", message: "Report has already been validated" }, status: 409 };
    }
    await this.repository.validate(reportId, {
      id: crypto.randomUUID(),
      reportId,
      validatedBy: userId,
      status: validated.data.status,
      notes: validated.data.notes
    });
    return { data: { id: reportId, status: validated.data.status }, status: 200 };
  }
}

// src/modules/report/report.controller.ts
class ReportController {
  module = new ReportModule;
  async create(c2) {
    const user2 = c2.get("user");
    const body = await c2.req.parseBody();
    const result = await this.module.processCreate(user2.id, body);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Report created"), 201);
  }
  async findMyReports(c2) {
    const user2 = c2.get("user");
    const query = c2.req.query();
    const result = await this.module.fetchMyReports(user2.id, query);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    const { items, page, limit, total } = result.data;
    return c2.json(paginatedResponse(items, { page, limit, total }));
  }
  async findAll(c2) {
    const query = c2.req.query();
    const result = await this.module.fetchAllReports(query);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    const { items, page, limit, total } = result.data;
    return c2.json(paginatedResponse(items, { page, limit, total }));
  }
  async getDetail(c2) {
    const id2 = c2.req.param("id");
    const result = await this.module.fetchDetail(id2);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Report fetched"));
  }
  async getMyDetail(c2) {
    const id2 = c2.req.param("id");
    const user2 = c2.get("user");
    const result = await this.module.fetchDetail(id2);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    if (result.data.userId !== user2.id) {
      return c2.json({ message: "Forbidden", error: { code: "FORBIDDEN", message: "Not your report" } }, 403);
    }
    return c2.json(successResponse(result.data, "Report fetched"));
  }
  async validate(c2) {
    const id2 = c2.req.param("id");
    const user2 = c2.get("user");
    const body = await c2.req.json();
    const result = await this.module.processValidate(id2, user2.id, body);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Report validated"));
  }
}

