// src/modules/office/office.modul.ts
function mapInput(input) {
  const { zoneType, polygon, ...rest } = input;
  const mapped = { ...rest };
  if (zoneType !== undefined)
    mapped.zone_type = zoneType;
  if (polygon !== undefined)
    mapped.polygon = polygon === null ? null : JSON.stringify(polygon);
  return mapped;
}

class OfficeModule {
  repository = new OfficeRepository;
  async fetchAll(query) {
    const validated = findOfficesQuerySchema.safeParse(query);
    if (!validated.success) {
      return {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid query",
          details: validated.error.flatten()
        },
        status: 422,
        data: { items: [], page: 1, limit: 0, total: 0 }
      };
    }
    const data = await this.repository.findAll(validated.data);
    return { data, status: 200 };
  }
  async fetchOne(id2) {
    const data = await this.repository.findById(id2);
    if (!data)
      return { error: { code: "OFFICE_NOT_FOUND", message: "Office not found" }, status: 404 };
    return { data, status: 200 };
  }
  async processCreate(body) {
    const validated = createOfficeSchema.safeParse(body);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid data", details: validated.error.flatten() }, status: 422 };
    }
    const data = await this.repository.create(mapInput(validated.data));
    return { data, status: 201 };
  }
  async processUpdate(id2, body) {
    const validated = updateOfficeSchema.safeParse(body);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid data" }, status: 422 };
    }
    const data = await this.repository.update(id2, mapInput(validated.data));
    if (!data)
      return { error: { code: "OFFICE_NOT_FOUND", message: "Office not found" }, status: 404 };
    return { data, status: 200 };
  }
  async processDelete(id2) {
    await this.repository.delete(id2);
    return { status: 200 };
  }
}

