class PermitRepository {
  async create(data) {
    const id2 = crypto.randomUUID();
    return await db2.insertInto("permit").values({
      id: id2,
      ...data,
      status: "pending"
    }).returningAll().executeTakeFirstOrThrow();
  }
  async findAll(filters) {
    let base = db2.selectFrom("permit").innerJoin("user", "user.id", "permit.userId");
    if (filters.userId) {
      base = base.where("permit.userId", "=", filters.userId);
    }
    if (filters.status) {
      base = base.where("permit.status", "=", filters.status);
    }
    if (filters.category) {
      base = base.where("permit.category", "=", filters.category);
    }
    const offset = (filters.page - 1) * filters.limit;
    const [rows, countResult] = await Promise.all([
      base.select([
        "permit.id",
        "permit.userId",
        "permit.type",
        "permit.category",
        "permit.description",
        "permit.startDate",
        "permit.endDate",
        "permit.attachmentUrl",
        "permit.status",
        "permit.notes",
        "permit.overtimeHours",
        "permit.reimburseAmount",
        "permit.reimburseReceiptUrl",
        "permit.loanAmount",
        "permit.loanTenorMonths",
        "permit.createdAt",
        "user.name as userName",
        "user.department as userDepartment"
      ]).limit(filters.limit).offset(offset).orderBy("permit.createdAt", "desc").execute(),
      base.select(sql`count(*)`.as("count")).executeTakeFirst()
    ]);
    const items = rows.map((r2) => ({
      id: r2.id,
      userId: r2.userId,
      type: r2.type,
      category: r2.category,
      description: r2.description,
      startDate: r2.startDate,
      endDate: r2.endDate,
      attachmentUrl: r2.attachmentUrl,
      status: r2.status,
      notes: r2.notes,
      overtimeHours: r2.overtimeHours,
      reimburseAmount: r2.reimburseAmount,
      reimburseReceiptUrl: r2.reimburseReceiptUrl,
      loanAmount: r2.loanAmount,
      loanTenorMonths: r2.loanTenorMonths,
      createdAt: r2.createdAt,
      user: {
        id: r2.userId,
        name: r2.userName,
        department: r2.userDepartment
      }
    }));
    return {
      items,
      page: filters.page,
      limit: filters.limit,
      total: Number(countResult?.count ?? 0)
    };
  }
  async findByUserId(userId) {
    return await db2.selectFrom("permit").selectAll().where("userId", "=", userId).orderBy("createdAt", "desc").execute();
  }
  async findById(id2) {
    return await db2.selectFrom("permit").selectAll().where("id", "=", id2).executeTakeFirst();
  }
  async validate(id2, data) {
    return await db2.updateTable("permit").set({
      status: data.status,
      notes: data.notes,
      updatedAt: new Date
    }).where("id", "=", id2).returningAll().executeTakeFirst();
  }
}

