init_esm();

class LeaveBalanceRepository {
  async getOrCreate(userId, year2) {
    const existing = await db2.selectFrom("leave_balance").selectAll().where("user_id", "=", userId).where("year", "=", year2).executeTakeFirst();
    if (existing)
      return existing;
    return await db2.insertInto("leave_balance").values({
      user_id: userId,
      year: year2,
      total_days: 12,
      used_days: 0
    }).returningAll().executeTakeFirstOrThrow();
  }
  async findAll(filters) {
    const { page, limit, year: year2 } = filters;
    const offset = (page - 1) * limit;
    const rows = await db2.selectFrom("user").leftJoin("leave_balance", (join2) => join2.onRef("leave_balance.user_id", "=", "user.id").on("leave_balance.year", "=", year2)).select([
      "user.id as userId",
      "user.name as userName",
      "user.department as userDepartment",
      "leave_balance.year",
      "leave_balance.total_days",
      "leave_balance.used_days",
      "leave_balance.notes"
    ]).orderBy("user.name", "asc").limit(limit).offset(offset).execute();
    const countResult = await db2.selectFrom("user").select(sql`count(*)`.as("count")).executeTakeFirst();
    const items = rows.map((r2) => {
      const totalDays = r2.total_days != null ? Number(r2.total_days) : 12;
      const usedDays = r2.used_days != null ? Number(r2.used_days) : 0;
      return {
        userId: r2.userId,
        year: r2.year ?? year2,
        totalDays,
        usedDays,
        remainingDays: totalDays - usedDays,
        notes: r2.notes ?? null,
        user: {
          id: r2.userId,
          name: r2.userName,
          department: r2.userDepartment
        }
      };
    });
    return {
      items,
      page,
      limit,
      total: Number(countResult?.count ?? 0)
    };
  }
  async upsert(userId, data) {
    const existing = await db2.selectFrom("leave_balance").selectAll().where("user_id", "=", userId).where("year", "=", data.year).executeTakeFirst();
    if (existing) {
      return await db2.updateTable("leave_balance").set({
        total_days: data.totalDays,
        ...data.usedDays !== undefined ? { used_days: data.usedDays } : {},
        ...data.notes !== undefined ? { notes: data.notes } : {},
        updated_at: new Date
      }).where("user_id", "=", userId).where("year", "=", data.year).returningAll().executeTakeFirstOrThrow();
    }
    return await db2.insertInto("leave_balance").values({
      user_id: userId,
      year: data.year,
      total_days: data.totalDays,
      used_days: data.usedDays ?? 0,
      notes: data.notes ?? null
    }).returningAll().executeTakeFirstOrThrow();
  }
  async adjustUsed(userId, year2, deltaDays) {
    const row = await this.getOrCreate(userId, year2);
    const current = Number(row.used_days);
    const next = Math.max(0, current + deltaDays);
    return await db2.updateTable("leave_balance").set({ used_days: next, updated_at: new Date }).where("user_id", "=", userId).where("year", "=", year2).returningAll().executeTakeFirstOrThrow();
  }
}

