var httpUrl2 = exports_external.url().refine((v2) => {
  try {
    const p2 = new URL(v2).protocol;
    return p2 === "http:" || p2 === "https:";
  } catch {
    return false;
  }
}, { message: "URL must use http or https scheme" });
var createPermitSchema = exports_external.object({
  type: exports_external.enum(["sick", "leave", "permit"]),
  category: exports_external.enum(["leave", "sick", "permit", "overtime", "reimburse", "loan"]).optional(),
  description: exports_external.string().min(1),
  startDate: exports_external.string().transform((val) => new Date(val)),
  endDate: exports_external.string().transform((val) => new Date(val)),
  attachmentUrl: httpUrl2.optional(),
  overtimeHours: exports_external.number().positive().max(24).optional(),
  reimburseAmount: exports_external.number().positive().optional(),
  reimburseReceiptUrl: httpUrl2.optional(),
  loanAmount: exports_external.number().positive().optional(),
  loanTenorMonths: exports_external.number().int().positive().max(120).optional()
});
var validatePermitSchema = exports_external.object({
  status: exports_external.enum(["approved", "rejected"]),
  notes: exports_external.string().optional()
});

// src/modules/permit/permit.modul.ts
function countWorkingDays(start, end) {
  const a2 = new Date(start.getFullYear(), start.getMonth(), start.getDate());
  const b2 = new Date(end.getFullYear(), end.getMonth(), end.getDate());
  if (b2 < a2)
    return 0;
  let count = 0;
  const cursor = new Date(a2);
  while (cursor <= b2) {
    const day2 = cursor.getDay();
    if (day2 !== 0 && day2 !== 6)
      count++;
    cursor.setDate(cursor.getDate() + 1);
  }
  return count;
}

class PermitModule {
  repository = new PermitRepository;
  leaveRepo = new LeaveBalanceRepository;
  async fetchAll(query) {
    const page = Number(query.page || 1);
    const limit = Number(query.limit || 10);
    const status = query.status;
    const userId = query.userId;
    const category = query.category;
    const result = await this.repository.findAll({
      page,
      limit,
      status,
      userId,
      category
    });
    return { data: result, status: 200 };
  }
  async fetchMyPermits(userId) {
    const data = await this.repository.findByUserId(userId);
    return { data, status: 200 };
  }
  async processCreate(userId, body) {
    const validated = createPermitSchema.safeParse(body);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid data", details: validated.error.flatten() }, status: 422 };
    }
    const payload = validated.data;
    let daysUsed = null;
    const category = payload.category ?? payload.type;
    if (category === "overtime" && payload.overtimeHours == null) {
      return {
        error: { code: "OVERTIME_HOURS_REQUIRED", message: "overtimeHours wajib diisi untuk lembur" },
        status: 422
      };
    }
    if (category === "reimburse" && payload.reimburseAmount == null) {
      return {
        error: { code: "REIMBURSE_AMOUNT_REQUIRED", message: "reimburseAmount wajib diisi untuk reimburse" },
        status: 422
      };
    }
    if (category === "loan" && (payload.loanAmount == null || payload.loanTenorMonths == null)) {
      return {
        error: { code: "LOAN_FIELDS_REQUIRED", message: "loanAmount dan loanTenorMonths wajib diisi untuk pinjaman" },
        status: 422
      };
    }
    if (category === "leave") {
      daysUsed = countWorkingDays(payload.startDate, payload.endDate);
      const year2 = payload.startDate.getFullYear();
      const balance = await this.leaveRepo.getOrCreate(userId, year2);
      const totalDays = Number(balance.total_days);
      const usedDays = Number(balance.used_days);
      if (usedDays + daysUsed > totalDays) {
        return {
          error: {
            code: "LEAVE_BALANCE_EXCEEDED",
            message: "Sisa cuti tidak cukup",
            details: { totalDays, usedDays, requested: daysUsed }
          },
          status: 422
        };
      }
    }
    const data = await this.repository.create({
      userId,
      ...payload,
      category,
      daysUsed
    });
    return { data, status: 201 };
  }
  async processValidate(id2, body) {
    const validated = validatePermitSchema.safeParse(body);
    if (!validated.success) {
      return { error: { code: "VALIDATION_ERROR", message: "Invalid data" }, status: 422 };
    }
    const existing = await this.repository.findById(id2);
    if (!existing)
      return { error: { code: "PERMIT_NOT_FOUND", message: "Permit not found" }, status: 404 };
    const prevStatus = existing.status;
    const data = await this.repository.validate(id2, validated.data);
    if (!data)
      return { error: { code: "PERMIT_NOT_FOUND", message: "Permit not found" }, status: 404 };
    if (data.type === "leave" && data.daysUsed != null) {
      const days = Number(data.daysUsed);
      const year2 = new Date(data.startDate).getFullYear();
      if (prevStatus !== "approved" && data.status === "approved") {
        await this.leaveRepo.adjustUsed(data.userId, year2, days);
      } else if (prevStatus === "approved" && data.status === "rejected") {
        await this.leaveRepo.adjustUsed(data.userId, year2, -days);
      }
    }
    return { data, status: 200 };
  }
}

