// src/modules/me/me.modul.ts
var ALLOWED_IMAGE_MIME = new Set(["image/jpeg", "image/png"]);
var MAX_AVATAR_BYTES = 5 * 1024 * 1024;
function sniffImageMime(buf) {
  if (buf.length >= 3 && buf[0] === 255 && buf[1] === 216 && buf[2] === 255) {
    return "image/jpeg";
  }
  if (buf.length >= 8 && buf[0] === 137 && buf[1] === 80 && buf[2] === 78 && buf[3] === 71 && buf[4] === 13 && buf[5] === 10 && buf[6] === 26 && buf[7] === 10) {
    return "image/png";
  }
  return null;
}

class MeModule {
  repository = new MeRepository;
  async processUpdate(userId, body) {
    const validated = updateMeSchema.safeParse(body);
    if (!validated.success) {
      return {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid data",
          details: validated.error.flatten()
        },
        status: 422
      };
    }
    if (validated.data.name === undefined && validated.data.department === undefined) {
      return {
        error: { code: "EMPTY_PAYLOAD", message: "No fields to update" },
        status: 422
      };
    }
    const data = await this.repository.updateProfile(userId, validated.data);
    if (!data) {
      return { error: { code: "USER_NOT_FOUND", message: "User not found" }, status: 404 };
    }
    return { data, status: 200 };
  }
  async processAvatarUpload(userId, body) {
    const photo = body["photo"];
    if (!photo || typeof photo.arrayBuffer !== "function") {
      return {
        error: { code: "MISSING_PHOTO", message: "photo field is required" },
        status: 422
      };
    }
    const declaredType = photo.type;
    if (declaredType && !ALLOWED_IMAGE_MIME.has(declaredType)) {
      return {
        error: {
          code: "INVALID_MIME_TYPE",
          message: "Only image/jpeg and image/png are allowed"
        },
        status: 422
      };
    }
    const size = photo.size;
    if (typeof size === "number" && size > MAX_AVATAR_BYTES) {
      return {
        error: { code: "FILE_TOO_LARGE", message: "Max file size is 5MB" },
        status: 422
      };
    }
    const arrayBuf = await photo.arrayBuffer();
    const buf = Buffer.from(arrayBuf);
    if (buf.byteLength > MAX_AVATAR_BYTES) {
      return {
        error: { code: "FILE_TOO_LARGE", message: "Max file size is 5MB" },
        status: 422
      };
    }
    const sniffed = sniffImageMime(buf);
    if (!sniffed) {
      return {
        error: {
          code: "INVALID_IMAGE",
          message: "File is not a valid JPEG or PNG image"
        },
        status: 422
      };
    }
    const previous = await this.repository.findById(userId);
    const previousImageUrl = previous?.image;
    const normalized = await import_sharp2.default(buf).rotate().resize(1024, 1024, { fit: "cover", position: "centre" }).jpeg({
      quality: 85,
      mozjpeg: false,
      progressive: false,
      chromaSubsampling: "4:2:0"
    }).toBuffer();
    const key = `avatars/${userId}-${crypto.randomUUID()}.jpg`;
    const imageUrl = await uploadToR2(normalized, key, "image/jpeg");
    const updated = await this.repository.updateImage(userId, imageUrl);
    if (!updated) {
      return { error: { code: "USER_NOT_FOUND", message: "User not found" }, status: 404 };
    }
    if (previousImageUrl && previousImageUrl !== imageUrl) {
      const previousKey = r2KeyFromPublicUrl(previousImageUrl);
      if (previousKey) {
        deleteFromR2(previousKey);
      }
    }
    return { data: { imageUrl }, status: 200 };
  }
  async processFaceEnrollment(userId, body) {
    const validated = enrollFaceSchema.safeParse(body);
    if (!validated.success) {
      return {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid embedding",
          details: validated.error.flatten()
        },
        status: 422
      };
    }
    const updated = await this.repository.updateFaceEmbedding(userId, JSON.stringify(validated.data.embedding));
    if (!updated) {
      return { error: { code: "USER_NOT_FOUND", message: "User not found" }, status: 404 };
    }
    return {
      data: { faceRecognitionEnabled: true },
      status: 200
    };
  }
  async processRegisterDevice(userId, body) {
    const validated = registerDeviceSchema.safeParse(body);
    if (!validated.success) {
      return {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid device payload",
          details: validated.error.flatten()
        },
        status: 422
      };
    }
    const data = await this.repository.setFcmToken(userId, validated.data.fcmToken);
    return { data, status: 200 };
  }
}

