class MeController {
  module = new MeModule;
  async updateProfile(c2) {
    const user2 = c2.get("user");
    const body = await c2.req.json();
    const result = await this.module.processUpdate(user2.id, body);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Profile updated"));
  }
  async enrollFace(c2) {
    const user2 = c2.get("user");
    const body = await c2.req.json();
    const result = await this.module.processFaceEnrollment(user2.id, body);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Face enrolled"));
  }
  async registerDevice(c2) {
    const user2 = c2.get("user");
    const body = await c2.req.json();
    const result = await this.module.processRegisterDevice(user2.id, body);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Device registered"));
  }
  async uploadAvatar(c2) {
    const user2 = c2.get("user");
    try {
      const body = await c2.req.parseBody();
      const result = await this.module.processAvatarUpload(user2.id, body);
      if (result.error) {
        return c2.json({ message: result.error.message, error: result.error }, result.status);
      }
      return c2.json(successResponse(result.data, "Avatar updated"));
    } catch (e2) {
      const code = classifyAvatarError(e2);
      console.error("[me/avatar] upload failed", {
        userId: user2?.id,
        code,
        errorName: e2?.name,
        errorCode: e2?.code,
        httpStatusCode: e2?.$metadata?.httpStatusCode
      });
      return c2.json({ message: "Failed to upload avatar", error: { code } }, 500);
    }
  }
  async streamAvatar(c2) {
    const user2 = c2.get("user");
    try {
      const repo = new MeRepository;
      const row = await repo.findById(user2.id);
      const url2 = row?.image;
      if (!url2) {
        return c2.json({ error: { code: "NO_AVATAR" } }, 404);
      }
      const key = r2KeyFromPublicUrl(url2);
      if (!key) {
        return c2.json({ error: { code: "INVALID_AVATAR_URL" } }, 500);
      }
      const obj = await r2Client.send(new GetObjectCommand({
        Bucket: process.env.R2_BUCKET_NAME,
        Key: key
      }));
      const body = obj.Body;
      if (!body) {
        return c2.json({ error: { code: "AVATAR_NOT_FOUND" } }, 404);
      }
      const arrayBuf = await body.transformToByteArray();
      return new Response(arrayBuf, {
        status: 200,
        headers: {
          "Content-Type": obj.ContentType ?? "image/png",
          "Cache-Control": "private, max-age=300"
        }
      });
    } catch (e2) {
      console.error("[me/avatar/stream] failed", {
        userId: user2?.id,
        errorName: e2?.name,
        httpStatusCode: e2?.$metadata?.httpStatusCode
      });
      return c2.json({ error: { code: "STREAM_FAILED" } }, 500);
    }
  }
}
function classifyAvatarError(e2) {
  const httpStatus = e2?.$metadata?.httpStatusCode;
  const name = e2?.name ?? "";
  const code = e2?.code ?? "";
  if (typeof httpStatus === "number" || name.includes("S3") || e2?.$fault) {
    return "STORAGE_UNAVAILABLE";
  }
  if (name === "TypeError" && /parseBody|FormData/i.test(String(e2?.stack ?? ""))) {
    return "INVALID_UPLOAD";
  }
  if (code === "ERR_INVALID_ARG_TYPE" || /image|jpeg|png|sharp/i.test(name)) {
    return "IMAGE_PROCESSING_FAILED";
  }
  return "AVATAR_UPLOAD_FAILED";
}

