init_esm();
function mapRow(r2) {
  return {
    id: r2.id,
    title: r2.title,
    body: r2.body,
    priority: r2.priority,
    isPinned: r2.isPinned,
    publishedAt: r2.publishedAt,
    expiresAt: r2.expiresAt,
    createdAt: r2.createdAt,
    updatedAt: r2.updatedAt,
    publishedBy: r2.publisherId ? { id: r2.publisherId, name: r2.publisherName } : { id: r2.publishedBy, name: null }
  };
}

class AnnouncementRepository {
  async create(data) {
    const row = await db2.insertInto("announcement").values({
      title: data.title,
      body: data.body,
      priority: data.priority,
      isPinned: data.isPinned,
      publishedBy: data.publishedBy,
      expiresAt: data.expiresAt ?? null
    }).returningAll().executeTakeFirstOrThrow();
    return this.findById(row.id);
  }
  async findAllWeb(filters) {
    let base = db2.selectFrom("announcement").leftJoin("user", "user.id", "announcement.publishedBy").select([
      "announcement.id",
      "announcement.title",
      "announcement.body",
      "announcement.priority",
      "announcement.isPinned",
      "announcement.publishedBy",
      "announcement.publishedAt",
      "announcement.expiresAt",
      "announcement.createdAt",
      "announcement.updatedAt",
      "user.id as publisherId",
      "user.name as publisherName"
    ]);
    if (filters.priority) {
      base = base.where("announcement.priority", "=", filters.priority);
    }
    const offset = (filters.page - 1) * filters.limit;
    const [rows, countResult] = await Promise.all([
      base.orderBy("announcement.isPinned", "desc").orderBy("announcement.publishedAt", "desc").limit(filters.limit).offset(offset).execute(),
      (filters.priority ? db2.selectFrom("announcement").where("priority", "=", filters.priority).select(sql`count(*)`.as("count")) : db2.selectFrom("announcement").select(sql`count(*)`.as("count"))).executeTakeFirst()
    ]);
    return {
      items: rows.map(mapRow),
      page: filters.page,
      limit: filters.limit,
      total: Number(countResult?.count ?? 0)
    };
  }
  async findAllMobile(filters) {
    const now2 = new Date;
    const base = db2.selectFrom("announcement").leftJoin("user", "user.id", "announcement.publishedBy").select([
      "announcement.id",
      "announcement.title",
      "announcement.body",
      "announcement.priority",
      "announcement.isPinned",
      "announcement.publishedBy",
      "announcement.publishedAt",
      "announcement.expiresAt",
      "announcement.createdAt",
      "announcement.updatedAt",
      "user.id as publisherId",
      "user.name as publisherName"
    ]).where((eb) => eb.or([
      eb("announcement.expiresAt", "is", null),
      eb("announcement.expiresAt", ">", now2)
    ]));
    const offset = (filters.page - 1) * filters.limit;
    const [rows, countResult] = await Promise.all([
      base.orderBy("announcement.isPinned", "desc").orderBy("announcement.publishedAt", "desc").limit(filters.limit).offset(offset).execute(),
      db2.selectFrom("announcement").where((eb) => eb.or([
        eb("expiresAt", "is", null),
        eb("expiresAt", ">", now2)
      ])).select(sql`count(*)`.as("count")).executeTakeFirst()
    ]);
    return {
      items: rows.map(mapRow),
      page: filters.page,
      limit: filters.limit,
      total: Number(countResult?.count ?? 0)
    };
  }
  async findById(id2) {
    const row = await db2.selectFrom("announcement").leftJoin("user", "user.id", "announcement.publishedBy").select([
      "announcement.id",
      "announcement.title",
      "announcement.body",
      "announcement.priority",
      "announcement.isPinned",
      "announcement.publishedBy",
      "announcement.publishedAt",
      "announcement.expiresAt",
      "announcement.createdAt",
      "announcement.updatedAt",
      "user.id as publisherId",
      "user.name as publisherName"
    ]).where("announcement.id", "=", id2).executeTakeFirst();
    return row ? mapRow(row) : null;
  }
  async update(id2, data) {
    const patch = { updatedAt: new Date };
    if (data.title !== undefined)
      patch.title = data.title;
    if (data.body !== undefined)
      patch.body = data.body;
    if (data.priority !== undefined)
      patch.priority = data.priority;
    if (data.isPinned !== undefined)
      patch.isPinned = data.isPinned;
    if (data.expiresAt !== undefined)
      patch.expiresAt = data.expiresAt;
    const updated = await db2.updateTable("announcement").set(patch).where("id", "=", id2).returningAll().executeTakeFirst();
    if (!updated)
      return null;
    return this.findById(id2);
  }
  async delete(id2) {
    return await db2.deleteFrom("announcement").where("id", "=", id2).execute();
  }
}

