// src/lib/fcm.ts
var cached2 = null;
var initFailed = false;
function loadAdmin() {
  if (initFailed)
    return null;
  if (cached2)
    return cached2;
  const b64 = process.env.FIREBASE_SA_JSON_BASE64;
  if (!b64) {
    initFailed = true;
    return null;
  }
  try {
    const admin2 = require_lib6();
    if (admin2.apps.length === 0) {
      const json3 = JSON.parse(Buffer.from(b64, "base64").toString("utf8"));
      admin2.initializeApp({
        credential: admin2.credential.cert(json3)
      });
    }
    cached2 = admin2;
    return admin2;
  } catch (e2) {
    console.error("[fcm] init failed", { name: e2?.name, message: e2?.message });
    initFailed = true;
    return null;
  }
}
async function broadcast(payload) {
  const admin2 = loadAdmin();
  if (!admin2)
    return 0;
  const rows = await db2.selectFrom("user").select(["fcmToken"]).where("fcmToken", "is not", null).execute();
  const tokens = rows.map((r2) => r2.fcmToken).filter((t8) => typeof t8 === "string" && t8.length > 0);
  if (tokens.length === 0)
    return 0;
  let total = 0;
  const messaging = admin2.messaging();
  const chunkSize = 500;
  for (let i2 = 0;i2 < tokens.length; i2 += chunkSize) {
    const slice = tokens.slice(i2, i2 + chunkSize);
    try {
      const res = await messaging.sendEachForMulticast({
        tokens: slice,
        notification: { title: payload.title, body: payload.body },
        data: payload.data
      });
      total += res.successCount;
    } catch (e2) {
      console.error("[fcm] broadcast chunk failed", { name: e2?.name });
    }
  }
  return total;
}

// src/modules/announcement/announcement.modul.ts
class AnnouncementModule {
  repository = new AnnouncementRepository;
  async fetchAllWeb(query) {
    const page = Math.max(1, Number(query.page) || 1);
    const limit = Math.min(100, Math.max(1, Number(query.limit) || 20));
    const priority = ["low", "normal", "high"].includes(query.priority) ? query.priority : undefined;
    const data = await this.repository.findAllWeb({ page, limit, priority });
    return { data, status: 200 };
  }
  async fetchAllMobile(query) {
    const page = Math.max(1, Number(query.page) || 1);
    const limit = Math.min(100, Math.max(1, Number(query.limit) || 20));
    const data = await this.repository.findAllMobile({ page, limit });
    return { data, status: 200 };
  }
  async fetchOne(id2) {
    const data = await this.repository.findById(id2);
    if (!data) {
      return {
        error: { code: "ANNOUNCEMENT_NOT_FOUND", message: "Announcement not found" },
        status: 404
      };
    }
    return { data, status: 200 };
  }
  async processCreate(publishedBy, body) {
    const validated = createAnnouncementSchema.safeParse(body);
    if (!validated.success) {
      return {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid data",
          details: validated.error.flatten()
        },
        status: 422
      };
    }
    const data = await this.repository.create({
      title: validated.data.title,
      body: validated.data.body,
      priority: validated.data.priority,
      isPinned: validated.data.isPinned,
      expiresAt: validated.data.expiresAt ?? null,
      publishedBy
    });
    if (data) {
      broadcast({
        title: data.title,
        body: data.body,
        data: { announcementId: String(data.id), type: "announcement" }
      }).catch(() => {});
    }
    return { data, status: 201 };
  }
  async processUpdate(id2, body) {
    const validated = updateAnnouncementSchema.safeParse(body);
    if (!validated.success) {
      return {
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid data",
          details: validated.error.flatten()
        },
        status: 422
      };
    }
    const data = await this.repository.update(id2, validated.data);
    if (!data) {
      return {
        error: { code: "ANNOUNCEMENT_NOT_FOUND", message: "Announcement not found" },
        status: 404
      };
    }
    return { data, status: 200 };
  }
  async processDelete(id2) {
    await this.repository.delete(id2);
    return { status: 200 };
  }
}

// src/modules/announcement/announcement.controller.ts
class AnnouncementController {
  module = new AnnouncementModule;
  async findAllWeb(c2) {
    const query = c2.req.query();
    const result = await this.module.fetchAllWeb(query);
    const { items, page, limit, total } = result.data;
    return c2.json(paginatedResponse(items, { page, limit, total }, "Announcements fetched"));
  }
  async findAllMobile(c2) {
    const query = c2.req.query();
    const result = await this.module.fetchAllMobile(query);
    const { items, page, limit, total } = result.data;
    return c2.json(paginatedResponse(items, { page, limit, total }, "Announcements fetched"));
  }
  async findOne(c2) {
    const id2 = c2.req.param("id");
    const result = await this.module.fetchOne(id2);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Announcement fetched"));
  }
  async create(c2) {
    const user2 = c2.get("user");
    const body = await c2.req.json();
    const result = await this.module.processCreate(user2.id, body);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Announcement created"), 201);
  }
  async update(c2) {
    const id2 = c2.req.param("id");
    const body = await c2.req.json();
    const result = await this.module.processUpdate(id2, body);
    if (result.error) {
      return c2.json({ message: result.error.message, error: result.error }, result.status);
    }
    return c2.json(successResponse(result.data, "Announcement updated"));
  }
  async delete(c2) {
    const id2 = c2.req.param("id");
    await this.module.processDelete(id2);
    return c2.json({ message: "Announcement deleted", data: null });
  }
}

