// src/app.ts
function createApp() {
  const app = new OpenAPIHono;
  app.get("/ui", middleware({ url: "/doc" }));
  app.doc("/doc", {
    openapi: "3.0.0",
    info: {
      version: "1.0.0",
      title: "FieldTrack API",
      description: "API Documentation for FieldTrack HRIS System"
    },
    servers: [
      {
        url: "http://localhost:3000",
        description: "Local server"
      },
      {
        url: "https://fieldtrack.vercel.app",
        description: "Production server"
      }
    ]
  });
  app.openAPIRegistry.registerComponent("securitySchemes", "Bearer", {
    type: "http",
    scheme: "bearer",
    bearerFormat: "JWT"
  });
  app.use("*", logger());
  const ALLOWED_ORIGINS = new Set([
    "http://localhost:5173",
    "http://localhost:3000",
    "https://fieldtrack.vercel.app",
    "https://stg-fieldtrack.vercel.app"
  ]);
  app.use("*", cors({
    origin: (origin) => {
      if (!origin)
        return null;
      return ALLOWED_ORIGINS.has(origin) ? origin : null;
    },
    credentials: true,
    allowHeaders: ["Content-Type", "Authorization", "X-Requested-With"],
    allowMethods: ["GET", "POST", "PATCH", "PUT", "DELETE", "OPTIONS"],
    exposeHeaders: ["set-auth-token"],
    maxAge: 86400
  }));
  app.all("/api/auth/*", (c2) => auth.handler(c2.req.raw));
  app.route("/api", user_route_default);
  app.route("/api", attendance_route_default);
  app.route("/api", report_route_default);
  app.route("/api", dashboard_route_default);
  app.route("/api", office_route_default);
  app.route("/api", permit_route_default);
  app.route("/api", leave_balance_route_default);
  app.route("/api", me_route_default);
  app.route("/api", announcement_route_default);
  app.get("/", (c2) => {
    return c2.json({ message: "FieldTrack API is running!" });
  });
  return app;
}

